SELECT (DATE_TRUNC('DAY', "SCHEDULED_AT")) AS "TIME_BUCKET", SUM(CASE WHEN STATE = 'SKIPPED' THEN 1 ELSE 0 END) AS "PIPE_SKIPPED_DOWNSTREAM" FROM (SELECT "NAME" AS TASK_NAME, "DATABASE_NAME" AS DATABASE_NAME, "SCHEMA_NAME" AS SCHEMA_NAME, "STATE" AS STATE, "ERROR_CODE" AS ERROR_CODE, "QUERY_ID" AS QUERY_ID, "GRAPH_ROOT_TASK_ID" AS GRAPH_ROOT_TASK_ID, "GRAPH_RUN_GROUP_ID" AS GRAPH_RUN_GROUP_ID, "RUN_ID" AS RUN_ID, (TRY_CAST("SCHEDULED_TIME" AS TIMESTAMP)) AS SCHEDULED_AT, (TRY_CAST("QUERY_START_TIME" AS TIMESTAMP)) AS STARTED_AT, (TRY_CAST("COMPLETED_TIME" AS TIMESTAMP)) AS COMPLETED_AT, (DATE_DIFF('SECOND', (TRY_CAST("SCHEDULED_TIME" AS TIMESTAMP)), (TRY_CAST("COMPLETED_TIME" AS TIMESTAMP)))) AS DURATION_SEC, PERCENT_RANK() OVER (PARTITION BY "NAME", ("_ACCOUNT") ORDER BY (DATE_DIFF('SECOND', (TRY_CAST("SCHEDULED_TIME" AS TIMESTAMP)), (TRY_CAST("COMPLETED_TIME" AS TIMESTAMP))))) AS DURATION_PERCENT_RANK, SUM(CASE WHEN "STATE" = 'FAILED' THEN 1 ELSE 0 END) OVER (PARTITION BY "NAME", ("_ACCOUNT")) AS TASK_FAILURE_COUNT, MAX(CASE WHEN "STATE" = 'SUCCEEDED' THEN (TRY_CAST("COMPLETED_TIME" AS TIMESTAMP)) END) OVER (PARTITION BY "NAME", ("_ACCOUNT")) AS LAST_SUCCESS_AT, MAX((TRY_CAST("SCHEDULED_TIME" AS TIMESTAMP))) OVER (PARTITION BY ("_ACCOUNT")) AS OBSERVED_THROUGH_AT, (DATE_DIFF('SECOND', MAX(CASE WHEN "STATE" = 'SUCCEEDED' THEN (TRY_CAST("COMPLETED_TIME" AS TIMESTAMP)) END) OVER (PARTITION BY "NAME", ("_ACCOUNT")), MAX((TRY_CAST("SCHEDULED_TIME" AS TIMESTAMP))) OVER (PARTITION BY ("_ACCOUNT")))) AS SECONDS_SINCE_LAST_SUCCESS, ("_ACCOUNT") AS ACCOUNT_NAME /* The account these rows came from (see the ACCOUNT_OF shim). */ FROM task_history) AS base GROUP BY (DATE_TRUNC('DAY', "SCHEDULED_AT")) ORDER BY "PIPE_SKIPPED_DOWNSTREAM" DESC, "TIME_BUCKET" LIMIT 100
